package com.fathom.category; import com.fathom.common.BaseEntity; import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="categories") public class Category extends BaseEntity { @Id private UUID id; @Column(name="user_id") private UUID userId; @Column(nullable=false) private String name; @Enumerated(EnumType.STRING) @Column(name="category_type",nullable=false) private CategoryType categoryType; @Column(name="parent_category_id") private UUID parentCategoryId; @Column(name="system_default",nullable=false) private boolean systemDefault=false; @Column(nullable=false) private boolean active=true; @PrePersist void init(){if(id==null)id=UUID.randomUUID();}
public UUID getId(){return id;} public UUID getUserId(){return userId;} public String getName(){return name;} public CategoryType getCategoryType(){return categoryType;} public boolean isSystemDefault(){return systemDefault;} public boolean isActive(){return active;} public void setUserId(UUID v){userId=v;} public void setName(String v){name=v;} public void setCategoryType(CategoryType v){categoryType=v;} public void setParentCategoryId(UUID v){parentCategoryId=v;} public void setSystemDefault(boolean v){systemDefault=v;} public void setActive(boolean v){active=v;} }
